/*
 * fuzz_cli.c — Argument handling and regression saving for ambre-fuzz.
 *
 * A violating image is a regression test (spec 7.7): the parent still holds
 * the generated bytes (the child only ever touched its fork copy), so saving
 * is a plain dump of the slot image plus a metadata file naming the seed,
 * the strategy and the replay command.
 */

#define _POSIX_C_SOURCE 200809L
#include "fuzz_run.h"
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

void usage(const char *argv0)
{
    fprintf(stderr,
        "usage: %s [--quick | --minutes N | --hours N] [--images N]\n"
        "          [--seed S] [--jobs N] [--timeout-ms N]\n"
        "          [--regress-dir DIR] [--report FILE] [--replay FILE]\n"
        "  --quick        bounded run of %.0f s (CI default)\n"
        "  --minutes N    run for N minutes (decimal allowed)\n"
        "  --hours N      run for N hours (the 24 h soak of spec 12.10)\n"
        "  --images N     stop after N generated images\n"
        "  --seed S       base seed (default %llu): image #i depends only\n"
        "                 on (seed, i), so any run is reproducible\n"
        "  --jobs N       parallel children, 1..%d (default %d)\n"
        "  --timeout-ms N per-image bound; exceeding it is a violation\n"
        "  --regress-dir  where violating images are saved (default %s)\n"
        "  --report FILE  write a JSON summary\n"
        "  --replay FILE  re-run one saved %llu-byte image and exit\n",
        argv0, FUZZ_QUICK_SECONDS, (unsigned long long)FUZZ_DEFAULT_SEED,
        FUZZ_MAX_JOBS, FUZZ_DEFAULT_JOBS, FUZZ_REGRESS_DIR,
        (unsigned long long)AMBRE_JOURNAL_BYTES);
}

bool opts_parse(fuzz_opts *o, int argc, char **argv)
{
    o->budget_s = FUZZ_QUICK_SECONDS;
    o->images = 0u;
    o->seed = FUZZ_DEFAULT_SEED;
    o->jobs = FUZZ_DEFAULT_JOBS;
    o->timeout_ms = FUZZ_TIMEOUT_MS;
    o->regress_dir = FUZZ_REGRESS_DIR;
    o->replay_file = NULL;
    o->report_json = NULL;
    for (int i = 1; i < argc; i++) {
        const char *a = argv[i];
        if (!strcmp(a, "--quick")) {
            o->budget_s = FUZZ_QUICK_SECONDS;
        } else if (!strcmp(a, "--minutes") && i + 1 < argc) {
            o->budget_s = 60.0 * strtod(argv[++i], NULL);
        } else if (!strcmp(a, "--hours") && i + 1 < argc) {
            o->budget_s = 3600.0 * strtod(argv[++i], NULL);
        } else if (!strcmp(a, "--images") && i + 1 < argc) {
            o->images = strtoull(argv[++i], NULL, 0);
        } else if (!strcmp(a, "--seed") && i + 1 < argc) {
            o->seed = strtoull(argv[++i], NULL, 0);
        } else if (!strcmp(a, "--jobs") && i + 1 < argc) {
            o->jobs = atoi(argv[++i]);
        } else if (!strcmp(a, "--timeout-ms") && i + 1 < argc) {
            o->timeout_ms = atoi(argv[++i]);
        } else if (!strcmp(a, "--regress-dir") && i + 1 < argc) {
            o->regress_dir = argv[++i];
        } else if (!strcmp(a, "--report") && i + 1 < argc) {
            o->report_json = argv[++i];
        } else if (!strcmp(a, "--replay") && i + 1 < argc) {
            o->replay_file = argv[++i];
        } else {
            usage(argv[0]);
            return false;
        }
    }
    if (o->jobs < 1 || o->jobs > FUZZ_MAX_JOBS || o->timeout_ms < 100 ||
        o->budget_s < 0.0) {
        usage(argv[0]);
        return false;
    }
    return true;
}

/* Sanitized kind token for file names. */
static void kind_token(char *out, size_t cap, int exit_code, int signo,
                       bool timed_out)
{
    if (timed_out) {
        snprintf(out, cap, "timeout");
    } else if (signo > 0) {
        snprintf(out, cap, "crash-sig%d", signo);
    } else {
        snprintf(out, cap, "check-%s", fuzz_fail_name(exit_code));
    }
}

void save_regression(const fuzz_slot *slot, const fuzz_opts *opts,
                     int exit_code, int signo, bool timed_out)
{
    char kind[64], img[512], meta[512];
    FILE *f;

    kind_token(kind, sizeof(kind), exit_code, signo, timed_out);
    if (mkdir(opts->regress_dir, 0755) != 0 && errno != EEXIST) {
        fprintf(stderr, "fuzz: cannot create %s: %s\n",
                opts->regress_dir, strerror(errno));
        return;
    }
    snprintf(img, sizeof(img), "%s/fuzz-%llu-%llu-%s.img", opts->regress_dir,
             (unsigned long long)opts->seed, (unsigned long long)slot->index,
             kind);
    snprintf(meta, sizeof(meta), "%s/fuzz-%llu-%llu-%s.txt", opts->regress_dir,
             (unsigned long long)opts->seed, (unsigned long long)slot->index,
             kind);
    f = fopen(img, "wb");
    if (f != NULL) {
        fwrite(slot->md.image, 1, (size_t)slot->md.size, f);
        fclose(f);
    }
    f = fopen(meta, "w");
    if (f != NULL) {
        fprintf(f, "seed=%llu\nindex=%llu\nstrategy=%s\nkind=%s\n"
                   "exit_code=%d\nsignal=%d (%s)\ntimeout_ms=%d\n"
                   "replay=ambre-fuzz --replay %s\n",
                (unsigned long long)opts->seed, (unsigned long long)slot->index,
                fuzz_strategy_name(slot->strategy), kind, exit_code, signo,
                signo > 0 ? strsignal(signo) : "-", opts->timeout_ms, img);
        fclose(f);
    }
    fprintf(stderr, "fuzz: VIOLATION seed=%llu index=%llu strategy=%s kind=%s"
                    " -> saved %s\n",
            (unsigned long long)opts->seed, (unsigned long long)slot->index,
            fuzz_strategy_name(slot->strategy), kind, img);
}
